fn Length(xs: List[Int]) -> Int
  requires len(xs) >= 0
  ensures result == len(xs)
  effects pure
  example Length([]) == 0
  example Length([1, 2, 3]) == 3
{
  match xs {
    [] => 0
    [_, ..t] => 1 + Length(t)
  }
}

fn PickMin(h: List[Int], m: List[Int]) -> List[Int]
  requires len(h) >= 0 and len(m) >= 0
  ensures result == h or result == m
  ensures len(result) <= len(h)
  ensures len(result) <= len(m)
  effects pure
  example PickMin([1], [1, 2]) == [1]
  example PickMin([1, 2], [1]) == [1]
  example PickMin([5, 5], [5, 5, 5]) == [5, 5]
{
  if Length(h) <= Length(m) then h else m
}

fn MinLengthSublist(s: List[List[Int]]) -> List[Int]
  requires (len(s) > 0)
  ensures contains(s, result)
  ensures forall sublist in s: (len(result) <= len(sublist))
  effects pure
  example MinLengthSublist([[1, 2, 3], [1], [1, 2]]) == [1]
  example MinLengthSublist([[5, 5], [5, 5, 5]]) == [5, 5]
{
  match s {
    [] => []
    [h, ..t] => match t {
      [] => h
      [_, .._] => PickMin(h, MinLengthSublist(t))
    }
  }
}

