fn IsUgly(x: Int) -> Bool
  requires (x > 0)
  ensures (result == (if x == 1 then true
                       else if x % 2 == 0 then IsUgly(x / 2)
                       else if x % 3 == 0 then IsUgly(x / 3)
                       else if x % 5 == 0 then IsUgly(x / 5)
                       else false))
  effects pure
  example IsUgly(1) == true
  example IsUgly(6) == true
  example IsUgly(14) == false
{
  if x == 1 then true
  else if x % 2 == 0 then IsUgly(x / 2)
  else if x % 3 == 0 then IsUgly(x / 3)
  else if x % 5 == 0 then IsUgly(x / 5)
  else false
}

fn CountUglyUpTo(limit: Int) -> Int
  requires (limit >= 0)
  ensures (result >= 0)
  ensures (result <= limit)
  effects pure
  example CountUglyUpTo(0) == 0
  example CountUglyUpTo(1) == 1
  example CountUglyUpTo(10) == 9
{
  if limit == 0 then 0
  else if IsUgly(limit) then CountUglyUpTo(limit - 1) + 1
  else CountUglyUpTo(limit - 1)
}

fn SearchNth(n: Int, limit: Int, budget: Int) -> Int
  requires (limit > 0)
  requires (budget >= 0)
  ensures (result > 0)
  effects pure
  example SearchNth(1, 1, 10) == 1
  example SearchNth(2, 1, 10) == 2
{
  if budget == 0 then limit
  else if CountUglyUpTo(limit) >= n then limit
  else SearchNth(n, limit + 1, budget - 1)
}

fn NthUglyNumber(n: Int) -> Int
  requires (n > 0)
  ensures (result > 0)
  effects pure
  example NthUglyNumber(1) == 1
  example NthUglyNumber(10) == 12
{
  SearchNth(n, 1, n * 100)
}

